  "tooltip": {"usage":{"lang":"svelte","code":"<button aria-describedby=\"tip\"\n  onmouseenter={() => showTip = true}\n  onmouseleave={() => showTip = false}\n  onfocusin={() => showTip = true}\n  onfocusout={() => showTip = false}\n>\n  Hover me\n</button>\n<Tooltip id=\"tip\" label=\"Additional info\" bind:visible={showTip} />\n"}},
  "tour": {"usage":{"lang":"svelte","code":"<Tour label=\"Onboarding tour\" bind:active>\n  <TourList label=\"Tour steps\">\n    <TourListItem label=\"Welcome\" current={step === 0} stepNumber={1} totalSteps={3}>\n      <p>Welcome to the app!</p>\n      <button onclick={() => step++}>Next</button>\n    </TourListItem>\n    <TourListItem label=\"Features\" current={step === 1} stepNumber={2} totalSteps={3}>\n      <p>Here are the features.</p>\n      <button onclick={() => step--}>Back</button>\n      <button onclick={() => step++}>Next</button>\n    </TourListItem>\n    <TourListItem label=\"Finish\" current={step === 2} stepNumber={3} totalSteps={3}>\n      <p>You're all set!</p>\n      <button onclick={() => active = false}>Done</button>\n    </TourListItem>\n  </TourList>\n</Tour>\n"}},
  "tour-list": {"usage":{"lang":"svelte","code":"<TourList label=\"Getting started\" bind:active>\n  <TourListItem label=\"Welcome\" current={step === 0} stepNumber={1} totalSteps={3}>\n    <p>Welcome to the app!</p>\n    <button onclick={() => step++}>Next</button>\n  </TourListItem>\n  <TourListItem label=\"Features\" current={step === 1} stepNumber={2} totalSteps={3}>\n    <p>Here are the features.</p>\n    <button onclick={() => step--}>Back</button>\n    <button onclick={() => step++}>Next</button>\n  </TourListItem>\n  <TourListItem label=\"Finish\" current={step === 2} stepNumber={3} totalSteps={3}>\n    <p>You're all set!</p>\n    <button onclick={() => active = false}>Done</button>\n  </TourListItem>\n</TourList>\n"}},
  "tour-list-item": {"usage":{"lang":"svelte","code":"<TourList label=\"Getting started\" bind:active>\n  <TourListItem label=\"Welcome\" current={step === 0} stepNumber={1} totalSteps={3}>\n    <p>Welcome to the app!</p>\n    <button onclick={() => step++}>Next</button>\n  </TourListItem>\n  <TourListItem label=\"Features\" current={step === 1} stepNumber={2} totalSteps={3}>\n    <p>Here are the features.</p>\n    <button onclick={() => step--}>Back</button>\n    <button onclick={() => step++}>Next</button>\n  </TourListItem>\n  <TourListItem label=\"Finish\" current={step === 2} stepNumber={3} totalSteps={3}>\n    <p>You're all set!</p>\n    <button onclick={() => active = false}>Done</button>\n  </TourListItem>\n</TourList>\n"}},
